example_solution:
create <- function(row, col) {
  if (row < 0) stop("row not positive")
  if (row > 7) stop("row not on board")
  if (col < 0) stop("column not positive")
  if (col > 7) stop("column not on board")
  list(row = row, col = col)
}

can_attack <- function(queen1, queen2) {
  same_row <- queen1$row == queen2$row
  same_col <- queen1$col == queen2$col
  same_diagonal <- abs(queen1$row - queen2$row) == abs(queen1$col - queen2$col)
  any(c(same_row, same_col, same_diagonal))
}

test_code:
source("./queen-attack.R")
library(testthat)

# Test creation of Queens with valid and invalid positions

test_that("queen with a valid position", {
  row <- 2
  col <- 2
  expect_no_error(create(row, col))
})

test_that("queen must have positive row", {
  row <- -2
  col <- 2
  expect_error(create(row, col))
})

test_that("queen must have row on board", {
  row <- 8
  col <- 4
  expect_error(create(row, col))
})

test_that("queen must have positive column", {
  row <- 2
  col <- -2
  expect_error(create(row, col))
})

test_that("queen must have column on board", {
  row <- 4
  col <- 8
  expect_error(create(row, col))
})

# Test the ability of one queen to attack another

test_that("cannot attack", {
  queen1 <- create(2, 4)
  queen2 <- create(6, 6)
  expect_false(can_attack(queen1, queen2))
})

test_that("can attack on same row", {
  queen1 <- create(2, 4)
  queen2 <- create(2, 6)
  expect_true(can_attack(queen1, queen2))
})

test_that("can attack on same column", {
  queen1 <- create(4, 5)
  queen2 <- create(2, 5)
  expect_true(can_attack(queen1, queen2))
})

test_that("can attack on first diagonal", {
  queen1 <- create(2, 2)
  queen2 <- create(0, 4)
  expect_true(can_attack(queen1, queen2))
})

test_that("can attack on second diagonal", {
  queen1 <- create(2, 2)
  queen2 <- create(3, 1)
  expect_true(can_attack(queen1, queen2))
})

test_that("can attack on third diagonal", {
  queen1 <- create(2, 2)
  queen2 <- create(1, 1)
  expect_true(can_attack(queen1, queen2))
})

test_that("can attack on fourth diagonal", {
  queen1 <- create(1, 7)
  queen2 <- create(0, 6)
  expect_true(can_attack(queen1, queen2))
})

# cannot attack if falling diagonals are only the same when reflected
# across the longest falling diagonal
test_that("cannot attack", {
  queen1 <- create(4, 1)
  queen2 <- create(2, 5)
  expect_false(can_attack(queen1, queen2))
})
